                MTH_SQRT_TO(xNorm, xSquaredNorm);
                if ((xNorm > 0.7f) && (xTmpReal < 0.0f)) {
                    *hCurrentMatrix = stPreviousMatrix;
                }
                bFlag = (p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags &
                         0x200000) ? 1 : 0;
                if (bFlag) {
