                p_stDynamic, lObstacle - lObstacle2,
                (g_a_stObstacle) + lObstacle2, &stTangentMove, &bFirstGround);
            bStep = 0;
            if (p_stGroundObstacle != 0) {
                bStep = MEC_fn_bDetectStep(
                    p_stDynamic, lObstacle - lObstacle2,
                    (g_a_stObstacle) + lObstacle2, p_stGroundObstacle,
                    &stTangentMove);
