                        bFlag =
                            (p_stDynamic->m_tdstDynamicsBaseBlock.ulEndFlags &
                             0x4000) ? 1 : 0;
                        if (bFlag &&
                            !(p_stDynamic->m_tdstDynamicsBaseBlock.m_pstReport
                                  ->m_ulPrevSurfaceState & 4)) {
