        pstDynamic = fn_p_stDynamGetDynamics(h_Dynam);
        if (pstDynamic) {
            if (pstDynamic->m_tdstDynamicsBaseBlock.ulEndFlags & 4 ? 1 : 0) {
                if (pstDynamic->m_tdstDynamicsComplexBlock.m_hPlatform == hFather) {
                    *p_lValue = 1;
